// 이전 노드에서 'content' 필드의 값을 가져옵니다.
const originalContent = $('Message a model(인트로)').first().json.message.content;
const img_url = $input.first().json.thumbnailLink;

// [IMG_INTRO_PLACE]를 <img src='ttt.png'>로 교체합니다.
const modifiedContent = originalContent.replace('[IMG_INTRO_PLACE]', "<img src='"+img_url+"'>");

// 수정된 'content' 값을 포함하는 새 아이템을 반환합니다.
// 기존 데이터 구조를 유지하면서 'content' 필드만 변경합니다.
return [{
  json: {
    content_intro: modifiedContent
  }
}];

// 이전 노드에서 'content' 필드의 값을 가져옵니다.
const originalContent = $('Message a model(본문)').first().json.message.content;
const img_url = $input.first().json.thumbnailLink;

// [IMG_BODY_PLACE]를 <img src='ttt.png'>로 교체합니다.
const modifiedContent = originalContent.replace('[IMG_BODY_PLACE]', "<img src='"+img_url+"'>");

// 수정된 'content' 값을 포함하는 새 아이템을 반환합니다.
// 기존 데이터 구조를 유지하면서 'content' 필드만 변경합니다.
return [{
  json: {
    content_body: modifiedContent
  }
}];

const content_intro = $('Code in JavaScript(인트로)').first().json.content_intro;
const content_body = $('Code in JavaScript(본문)').first().json.content_body;
const content_keyword = $('Message a model(검색어)').first().json.message.content;
const content_full = content_intro + '<br><br>' + content_body + '<br><br>' + content_keyword;

return {
  json: {
    full_name: content_full,
  },
};
